contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }

  // Drive the contract: caller tries to call sudicideAnyone; assert that non-owners cannot succeed.
  // param callerIsOwner: if true, the call is made from the owner address (expected to succeed on P);
  //                      if false, the call is made from a non-owner address (expected to revert on P).
  // We express success/failure via the low-level call boolean (no direct access to selfdestruct result).
  function runTest(bool callerIsOwner, address caller) public payable {
    require(caller != address(0), "provide non-zero caller");

    // If we want to simulate a call from the owner, require that caller equals the recorded owner getter.
    address owner = c.smartfix_owner();

    if (callerIsOwner) {
      require(caller == owner, "caller must equal recorded owner when callerIsOwner is true");
    } else {
      require(caller != owner, "caller must be different from owner when callerIsOwner is false");
    }

    // Make the call using low-level call to simulate msg.sender being `caller`.
    // We cannot actually change msg.sender in Solidity, but the verifier used with this harness will model the call origin.
    // Use a low-level call to obtain a boolean indicating whether the call succeeded (did not revert).
    (bool success, ) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));

    // The distinguishing rule: when the invoker is not the recorded owner, the call must fail (revert) on the original contract.
    // This holds for P (require check prevents non-owner calls) and is violated by M (require removed => non-owners succeed).
    assert(callerIsOwner ? true : (!success));
  }

  // Allow contract to receive ETH if needed by caller environment
  receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(true);
        bool reverted;
        // Call sudicideAnyone from the provided caller by using low-level call to change msg.sender
        // We cannot change msg.sender directly in Solidity, so we express the rule using the observed revert flag when called normally:
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        // The general rule: the call should revert unless msg.sender equals c.smartfix_owner(), which is observable via the public getter smartfix_owner
        // Express: reverted == (caller != c.smartfix_owner()) but since we actually invoked c.sudicideAnyone() with msg.sender == address(this), we relate to that.
        // Use the observable owner and the actual caller (address(this)) used in the call above
        assert(reverted == (address(this) != c.smartfix_owner()));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call the target function with a caller and assert that only owner can receive the selfdestruct (i.e., call succeeds only for owner).
    // We express this by checking that when we call sudicideAnyone from this contract, it reverts unless this contract is the owner.
    // The function takes a boolean flag "asOwner" indicating whether the test caller should be equal to the owner;
    // since we cannot change msg.sender, we instead read the public owner and compare to address(this) in the final assertion.
    // The distinguishing property: owner must be equal to the caller for the call to not revert.

    function runTest() public {
        // No state-changing calls needed before decision; we will attempt the call and capture whether it reverts via try/catch.
        bool didSucceed;
        try c.sudicideAnyone() {
            didSucceed = true;
        } catch {
            didSucceed = false;
        }

        // Observe the public owner via its autogenerated getter and assert the general rule:
        // If this contract is the owner then the call must have succeeded; otherwise it must have reverted.
        address owner = c.smartfix_owner();
        assert(didSucceed == (owner == address(this)));
    }

    // allow receiving ether if needed by the tested contract
    receive() external payable {}
}

